parameters.jsCode:
const webhookData = $('Webhook').item.json.body;
const aiResponse = $input.first().json;
const rawText = aiResponse.message.content;
const cleanText = rawText.replace(/```json\s*|```/g, '').trim();

let parsed;
try {
  parsed = JSON.parse(cleanText);
} catch (e) {
  parsed = {
    category: 'other',
    priority: 'medium',
    summary: webhookData.message,
    suggestedReply: 'Спасибо за обращение, мы скоро свяжемся с вами.'
  };
}

// Защита от formula injection в Google Sheets: если значение начинается с
// =, +, -, @ (или таба), Google/Excel могут исполнить его как формулу.
// Ведущий апостроф заставляет Sheets трактовать ячейку как текст.
function sanitize(value) {
  const str = String(value ?? '');
  return /^[=+\-@\t]/.test(str) ? "'" + str : str;
}

return [{
  json: {
    id: Date.now().toString(),
    timestamp: new Date().toISOString(),
    name: sanitize(webhookData.name),
    contact: sanitize(webhookData.contact),
    message: sanitize(webhookData.message),
    category: parsed.category,
    priority: parsed.priority,
    summary: sanitize(parsed.summary),
    suggestedReply: sanitize(parsed.suggestedReply),
    status: 'new'
  }
}];

